fast_pseudocode:
@triton.autotune(configs=[Config({'XBLOCK':256,'YBLOCK':8}, ...),...], key=[...])
@triton.jit
def kernel(...):
    ...

# CORRECT: grid uses meta to match autotuned tile sizes
grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
kernel[grid](args...)  # XBLOCK/YBLOCK injected automatically by autotune
